from pathlib import Path
import os,subprocess,hashlib,tempfile,shutil,json,base64,zlib,contextlib,io
assert Path('/sys/class/dmi/id/product_uuid').read_text().strip().lower()=='d9c423e9-ce89-3ba9-9cd8-f48cdb791da2'
FILES={'shared_directory_policy.py': '', 'ablestack-storagectl': ''}
CAPTURE=''
def capture():
 out=io.StringIO()
 with contextlib.redirect_stdout(out):exec(compile(zlib.decompress(base64.b64decode(CAPTURE)),'capture','exec'),{})
 return json.loads(out.getvalue())
def run(args,**kwargs):
 r=subprocess.run(args,capture_output=True,text=True,**kwargs)
 return {'rc':r.returncode,'out':r.stdout[-4000:],'err':r.stderr[-2000:]}
cli=Path('/usr/local/bin/ablestack-storagectl').resolve()
helper=cli.parent/'lib/ablestack-storage/shared_directory_policy.py'
assert helper.exists()
original={str(x):hashlib.sha256(x.read_bytes()).hexdigest() for x in cli.parent.rglob('*') if x.is_file()}
before=capture()
cold=run(['systemctl','is-active','--quiet','winbind.service'])
nss=run(['getent','passwd','ABLESTACK\\epic1453ad'])
assert cold['rc']!=0 and nss['rc']!=0
work=Path(tempfile.mkdtemp(prefix='epic1453-r6-pretest-',dir='/var/tmp'))
try:
 for name,data in FILES.items():
  (work/name).write_bytes(zlib.decompress(base64.b64decode(data)))
  (work/name).chmod(0o755)
 runner=work/'run.sh'
 runner.write_text('#!/bin/bash\nset -euo pipefail\nmount --make-rprivate /\nmount --bind '+str(work/'ablestack-storagectl')+' '+str(cli)+'\nmount --bind '+str(work/'shared_directory_policy.py')+' '+str(helper)+'\nexport ABLESTACK_STORAGE_BOOT_RECONCILE_ATTEMPTS=1\nexport ABLESTACK_STORAGE_BOOT_RECONCILE_LOG='+str(work/'boot.log')+'\nexec /usr/local/bin/ablestack-storage-boot-reconcile\n')
 replay=run(['unshare','--mount','bash',str(runner)],timeout=180)
 log=(work/'boot.log').read_text()
 after=capture()
 hashes={str(x):hashlib.sha256(x.read_bytes()).hexdigest() for x in cli.parent.rglob('*') if x.is_file()}
 checks={'cold':cold,'initialNss':nss,'replay':replay,'log':log,
 'winbind':run(['systemctl','is-active','winbind.service']),
 'defaultSmbd':run(['systemctl','is-active','smbd.service']),
 'trust':run(['wbinfo','-t']),
 'user':run(['getent','passwd','ABLESTACK\\epic1453ad']),
 'group':run(['getent','group','ABLESTACK\\epic1453writers']),
 'listeners':run(['ss','-lntp','sport = :445']),
 'before':before,'after':after,'signedPayloadUnchanged':hashes==original}
 print(json.dumps(checks))
 assert replay['rc']==0
 assert checks['winbind']['rc']==0 and checks['defaultSmbd']['rc']!=0
 assert checks['trust']['rc']==0 and checks['user']['rc']==0 and checks['group']['rc']==0
 assert before['objects']==after['objects'] and before['filesystem']==after['filesystem']
 assert hashes==original
finally:shutil.rmtree(work)
